<?php
$title='Dashboard';$subtitle='Welcome back, '.explode(' ',user()['name']??'')[0];
$p=array_map('intval',DB::row("SELECT SUM(source='maps') t,SUM(source='maps' AND map_score IS NOT NULL) au,SUM(source='maps' AND stage IN ('report_ready','contacting','contacted','opened','replied','won','lost')) rr,SUM(source='maps' AND (email_status IN ('sent','opened') OR wa_status IN ('sent','delivered','read','manual'))) ct,SUM(source='maps' AND (email_status='opened' OR wa_status='read' OR stage='opened')) op,SUM(source='maps' AND replied_at IS NOT NULL) rp,SUM(source='maps' AND is_lead=1) il,SUM(stage IN ('queued','auditing','reporting','contacting')) wk FROM leads"));
$c=DB::row("SELECT COUNT(*) t,SUM(created_at>=CURDATE()) td,SUM(created_at>=NOW()-INTERVAL 7 DAY) wk,SUM(status='won') wn,SUM(CASE WHEN status='won' THEN deal_value ELSE 0 END) wv,SUM(CASE WHEN status NOT IN ('won','lost') THEN deal_value ELSE 0 END) pv,SUM(follow_up_at IS NOT NULL AND follow_up_at<=NOW() AND status NOT IN ('won','lost')) due FROM leads WHERE is_lead=1");
$st=[];foreach(DB::all('SELECT status,COUNT(*) n FROM leads WHERE is_lead=1 GROUP BY status') as $r)$st[$r['status']]=(int)$r['n'];
$srcs=DB::all('SELECT source,COUNT(*) n FROM leads WHERE is_lead=1 GROUP BY source ORDER BY n DESC');
$appts=DB::all("SELECT a.*,l.name,l.contact_name FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE a.status='scheduled' AND a.start_at>=NOW()-INTERVAL 1 HOUR ORDER BY a.start_at LIMIT 5");
$fu=DB::all("SELECT id,name,contact_name,follow_up_at,phone FROM leads WHERE is_lead=1 AND follow_up_at IS NOT NULL AND follow_up_at<=NOW()+INTERVAL 1 DAY AND status NOT IN ('won','lost') ORDER BY follow_up_at LIMIT 6");
$ev=DB::all('SELECT e.*,l.name,l.contact_name FROM events e JOIN leads l ON l.id=e.lead_id ORDER BY e.id DESC LIMIT 14');
$ai=setting('ai_key_'.setting('ai_provider','anthropic'))!=='';
$maps=setting('maps_source')==='serpapi'?setting('serpapi_key')!=='':setting('google_api_key')!=='';
$checks=[[$ai,'Connect an AI provider','ai'],[$maps,'Add a Google Maps API key','settings&tab=data'],[Mailer::ready(),'Set up email (SMTP)','settings&tab=email'],[setting('wa_provider')!=='manual','Connect WhatsApp API (optional)','settings&tab=whatsapp'],[(bool)DB::val('SELECT COUNT(*) FROM sources'),'Capture leads from forms & ads','settings&tab=capture'],[(bool)DB::val('SELECT COUNT(*) FROM automations WHERE active=1'),'Switch on an automation','automations']];
$done=count(array_filter(array_column($checks,0)));
$fun=[['Scraped',$p['t'],'#94A3B8'],['Audited',$p['au'],'#60A5FA'],['Report ready',$p['rr'],'#A78BFA'],['Contacted',$p['ct'],'#FFC21A'],['Opened',$p['op'],'#2DD4BF'],['Replied',$p['rp'],'#4ADE80'],['Moved to Leads',$p['il'],'#16A34A']];$max=max(1,$p['t']);
$evic=['found'=>'pin','enriched'=>'globe','audited'=>'activity','stage'=>'zap','sent'=>'send','opened'=>'eye','viewed'=>'eye','replied'=>'msg','error'=>'alert','note'=>'edit','scheduled'=>'clock','wa_manual'=>'wa','call'=>'mic','auto'=>'bot','booked'=>'cal'];
?>
<div class="kpis"><div class="kpi"><span class="hi hi-g"><?=icon('users')?></span><div><span>Leads</span><b><?=(int)$c['t']?></b><small>+<?=(int)$c['wk']?> this week · <?=(int)$c['td']?> today</small></div></div><div class="kpi"><span class="hi hi-o"><?=icon('clock')?></span><div><span>Follow-ups due</span><b><?=(int)$c['due']?></b><small><a class="lnk" href="<?=url('leads',['fu'=>'due'])?>">Open list</a></small></div></div><div class="kpi"><span class="hi hi-b"><?=icon('send')?></span><div><span>Businesses contacted</span><b><?=$p['ct']?></b><small><?=$p['ct']?round($p['rp']/$p['ct']*100,1):0?>% reply rate</small></div></div><div class="kpi kpi-n"><span class="hi hi-y"><?=icon('target')?></span><div><span>Won</span><b><?=money($c['wv'])?></b><small><?=(int)$c['wn']?> deals · <?=money($c['pv'])?> in pipeline</small></div></div></div>
<?php if($done<count($checks)):?><div class="card"><div class="card-h"><h3><span class="hi hi-y"><?=icon('zap')?></span>Finish setting up Setu</h3><span class="muted"><?=$done?>/<?=count($checks)?> done</span></div><div class="prog"><i style="width:<?=round($done/count($checks)*100)?>%"></i></div><div class="steps"><?php foreach($checks as [$ok,$lb,$u]):?><a href="index.php?r=<?=$u?>" class="step <?=$ok?'ok':''?>"><?=icon($ok?'check':'clock')?><span><?=e($lb)?></span></a><?php endforeach?></div></div><?php endif?>
<div class="g2"><div class="card"><div class="card-h"><h3><span class="hi hi-g"><?=icon('kanban')?></span>Lead pipeline</h3><a class="lnk" href="<?=url('leads',['view'=>'board'])?>">Board</a></div><div class="fun"><?php $mx=max(1,max($st?:[0]));foreach(crm_statuses() as $k=>[$lb,$cl]):$n=$st[$k]??0;?><div class="fr"><span><?=e($lb)?></span><div><i style="width:<?=max(2,round($n/$mx*100))?>%;background:var(--<?=['blue'=>'blue','teal'=>'teal','purple'=>'purple','orange'=>'orange','gold'=>'y2','green'=>'green','red'=>'red'][$cl]?>)"></i></div><b><?=$n?></b></div><?php endforeach?></div><?php if($srcs):?><h4>Where leads come from</h4><div class="row"><?php foreach($srcs as $s):?><a href="<?=url('leads',['src'=>$s['source']])?>" class="bdg bdg-gray"><?=srcbadge($s['source'])?> <b><?=$s['n']?></b></a><?php endforeach?></div><?php endif?></div>
<div class="card"><div class="card-h"><h3><span class="hi hi-o"><?=icon('map')?></span>Prospecting funnel</h3><a class="lnk" href="<?=url('prospects')?>">Scraped data</a></div><div class="fun"><?php foreach($fun as [$lb,$n,$cl]):?><div class="fr"><span><?=e($lb)?></span><div><i style="width:<?=max(2,round($n/$max*100))?>%;background:<?=$cl?>"></i></div><b><?=$n?></b></div><?php endforeach?></div><?php if($p['wk']):?><p class="hint"><span class="spin"></span> <?=$p['wk']?> business(es) processing now – <a class="lnk" href="#" onclick="A.drawer(1);return false">view activity</a></p><?php endif?></div></div>
<div class="g2"><div class="card"><div class="card-h"><h3><span class="hi hi-t"><?=icon('cal')?></span>Today &amp; next</h3><a class="lnk" href="<?=url('appointments')?>">Calendar</a></div><?php if(!$appts&&!$fu):?><div class="empty sm"><?=icon('cal')?><p>No upcoming meetings or follow-ups.</p></div><?php endif?><?php foreach($appts as $a):?><div class="msg"><div class="msg-h"><?=icon('cal')?><b><?=e(date('D d M · h:i A',strtotime($a['start_at'])))?></b><span class="bdg bdg-teal">Meeting</span></div><p><a class="lnk" href="<?=url('lead',['id'=>$a['lead_id']])?>"><?=e($a['contact_name']?:$a['name'])?></a> · <?=e($a['title'])?></p></div><?php endforeach?><?php foreach($fu as $f):?><div class="msg"><div class="msg-h"><?=icon('clock')?><b><?=e(date('D d M · h:i A',strtotime($f['follow_up_at'])))?></b><span class="bdg bdg-<?=strtotime($f['follow_up_at'])<=time()?'red':'orange'?>">Follow-up</span></div><p><a class="lnk" href="<?=url('lead',['id'=>$f['id']])?>"><?=e($f['contact_name']?:$f['name'])?></a><?=$f['phone']?' · '.e($f['phone']):''?></p></div><?php endforeach?></div>
<div class="card"><div class="card-h"><h3><span class="hi hi-n"><?=icon('activity')?></span>Recent activity</h3></div><?php if(!$ev):?><div class="empty sm"><?=icon('activity')?><p>No activity yet. Start with a Map search or add a lead.</p></div><?php else:?><ul class="feed"><?php foreach($ev as $x):?><li class="ev-<?=e($x['type'])?>"><i></i><div><a href="<?=url('lead',['id'=>$x['lead_id']])?>"><b><?=e($x['contact_name']?:$x['name'])?></b></a> <span><?=e($x['message'])?></span><small><?=ago($x['created_at'])?></small></div></li><?php endforeach?></ul><?php endif?></div></div>
